@Test
@Transactional
void 반대만() {
    Team teamA = new Team("teamA");
    Member m = new Member("m1", 10);
    teamA.getMembers().add(m);     // 반대쪽만

    em.persist(teamA);
    em.persist(m);
    em.flush();

    System.out.println("비우기 전: " + teamA.getMembers().size());

    Long teamId = (Long) em.createNativeQuery(
            "select team_id from member").getSingleResult();
    System.out.println("DB 의 team_id: " + teamId);

    em.clear();
    Team found = queryFactory.selectFrom(team).fetchOne();
    System.out.println("비운 뒤:   " + found.getMembers().size());
}

