-- Querydsl 로 어느 쪽에서든 조인한다

@Test
@Transactional
void 양쪽_조인() {
    em.clear();
    System.out.println("--- member 에서 ---");
    queryFactory.selectFrom(member)
            .join(member.team, team)
            .where(team.name.eq("teamA"))
            .fetch();

    em.clear();
    System.out.println("--- team 에서 ---");
    queryFactory.selectFrom(team)
            .join(team.members, member)
            .where(member.username.eq("m1"))
            .fetch();
}

