-- cascade 는 컬럼을 안 채운다

@OneToMany(mappedBy = "team", cascade = CascadeType.ALL)
private List<Member> members = new ArrayList<>();

@Test
@Transactional
void cascade() {
    Team teamA = new Team("teamA");
    teamA.getMembers().add(new Member("m1", 10));   // 반대쪽만
    em.persist(teamA);
    em.flush(); em.clear();

    Long teamId = (Long) em.createNativeQuery(
            "select team_id from member").getSingleResult();
    System.out.println("DB 의 team_id: " + teamId);
}

